"""Finalize the completed mechanics-repair result with asserted summary metrics."""
import json
from pathlib import Path

PATH = Path('Training/experiments/mechanics-recovery-2026-09-17.json')


def main():
    record = json.loads(PATH.read_text())
    assert record['selectedStep'] == 64
    development = record['development']['64']['report']
    assert development['editPlanExact'] == {'applicable': 12, 'passed': 9}
    assert development['meaningPreservation'] == {'applicable': 12, 'passed': 12}
    assert development['contextFit'] == {'applicable': 12, 'passed': 10}
    contexts = record['diagnosticContexts']
    assert contexts['report']['editPlanExact'] == {'applicable': 256, 'passed': 227}
    assert contexts['report']['meaningPreservation'] == {'applicable': 256, 'passed': 234}
    assert contexts['report']['contextFit'] == {'applicable': 256, 'passed': 255}
    assert not contexts['physicalVocabularyAudit']['acceptedVocabularySubstitutionIDs']
    fit = record['mechanicsTrainingFit']['report']
    for key in ('editPlanExact', 'meaningPreservation', 'contextFit'):
        assert fit[key] == {'applicable': 128, 'passed': 128}
    record['conclusion'] = {
        'advance': False, 'selectedStep': 64,
        'reason': ('The repair fits all authored mechanics examples but regresses development to '
                   '9/12 exact and misses the focused-context meaning gate. It is rejected.'),
        'prospectiveQueried': False, 'frozenReleaseQueried': False, 'promoted': False}
    record['status'] = ('Completed and rejected: known regression gates failed; no prospective or '
                        'frozen release query and no promotion.')
    record['summarySource'] = Path(__file__).read_text()
    PATH.write_text(json.dumps(record, indent=2, sort_keys=True) + '\n')


if __name__ == '__main__':
    main()

